async function main(req) {
  const allowedOrigins = env('ALLOWED_ORIGINS', '*').split(',').map(s => s.trim());
  const allowedTargets = env('ALLOWED_TARGETS', '').split(',').map(s => s.trim());
  const origin = (req.headers || {})['Origin'] || (req.headers || {})['origin'] || '';

  const corsHeaders = {
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    'Access-Control-Max-Age': '86400'
  };

  // Check origin
  if (allowedOrigins[0] === '*' || allowedOrigins.includes(origin)) {
    corsHeaders['Access-Control-Allow-Origin'] = origin || '*';
  } else {
    return { status: 403, body: jsonStringify({ error: 'origin not allowed' }) };
  }

  // Handle preflight
  if (req.method === 'OPTIONS') {
    return { status: 204, headers: corsHeaders, body: '' };
  }

  const body = jsonParse(req.body, {});
  const targetUrl = body.url;
  if (!targetUrl) {
    return { status: 400, headers: corsHeaders, body: jsonStringify({ error: 'url field required' }) };
  }

  // Validate target domain
  try {
    const hostname = new URL(targetUrl).hostname;
    if (allowedTargets.length > 0 && allowedTargets[0] !== '' && !allowedTargets.includes(hostname)) {
      return { status: 403, headers: corsHeaders, body: jsonStringify({ error: 'target domain not allowed' }) };
    }
  } catch (_) {
    return { status: 400, headers: corsHeaders, body: jsonStringify({ error: 'invalid url' }) };
  }

  try {
    const resp = await fetch(targetUrl, { method: body.method || 'GET' });
    const data = await resp.text();
    return {
      status: resp.status,
      headers: { ...corsHeaders, 'Content-Type': resp.headers['content-type'] || 'application/json' },
      body: data
    };
  } catch (err) {
    return { status: 502, headers: corsHeaders, body: jsonStringify({ error: 'upstream error', detail: err.message }) };
  }
}
